"use client";

import * as React from "react";
import { DayPicker } from "react-day-picker";
import { cn } from "../../lib/utils.js";

/*
 * react-day-picker v9 renders each caption-layout dropdown as:
 *   <span class="rdp-dropdown_root">
 *     <select class="rdp-dropdown">…</select>
 *     <span aria-hidden="true">{label}<chevron/></span>
 *   </span>
 * The library expects the consumer's theme to layer the native <select>
 * transparently over the visible label span. Without that overlay both
 * elements paint side-by-side and the month/year labels duplicate. We use a
 * plain <style> block (rather than Tailwind arbitrary variants) because the
 * `_` in the rdp class names trips up Tailwind's underscore-as-space rule and
 * RDP v9's ClassNames merger doesn't run user classes for these keys.
 */
const RDP_DROPDOWN_OVERLAY_CSS = `
.rdp-dropdowns {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: var(--gap-sm, 0.5rem);
	font-size: 0.875rem;
	font-weight: 500;
}
.rdp-dropdown_root {
	position: relative;
	display: inline-flex;
	align-items: center;
	gap: var(--space-1, 0.25rem);
	border-radius: 0.375rem;
	padding: var(--space-1, 0.25rem) var(--space-2, 0.5rem);
	transition: background-color var(--duration-normal, 200ms) ease-out;
}
.rdp-dropdown_root:hover {
	background-color: hsl(var(--accent));
}
.rdp-dropdown_root:has(:focus-visible) {
	outline: 2px solid hsl(var(--ring));
	outline-offset: 2px;
}
.rdp-dropdown {
	position: absolute;
	inset: 0;
	z-index: 10;
	width: 100%;
	height: 100%;
	cursor: pointer;
	appearance: none;
	background: transparent;
	border: 0;
	opacity: 0;
}
.rdp-dropdown:disabled {
	cursor: not-allowed;
}
`;

/**
 * Calendar date grid built on react-day-picker v9. Forwards all DayPicker
 * props. Pair `mode` + `selected` + `onSelect` for selection control;
 * pass `captionLayout="dropdown"` with `startMonth`/`endMonth` for
 * native year-dropdown navigation.
 * @returns A themed react-day-picker instance with our dropdown overlay CSS.
 */
function Calendar({
	className,
	classNames,
	showOutsideDays = true,
	...props
}: React.ComponentProps<typeof DayPicker>) {
	return (
		<>
			<style
				// Single static stylesheet; React inlines once per page
				// regardless of Calendar instance count.
				dangerouslySetInnerHTML={{ __html: RDP_DROPDOWN_OVERLAY_CSS }}
			/>
		<DayPicker
			showOutsideDays={showOutsideDays}
			className={cn("relative p-[var(--space-3,0.75rem)]", className)}
			classNames={{
				months: "flex flex-col sm:flex-row gap-[var(--gap-md,1rem)]",
				month: "flex flex-col gap-[var(--gap-md,1rem)]",
				month_caption: "flex h-7 items-center justify-center",
				caption_label: "text-sm font-medium",
				nav: "absolute inset-x-3 top-3 z-10 flex items-center justify-between pointer-events-none [&>button]:pointer-events-auto",
				button_previous: cn(
					"inline-flex h-7 w-7 items-center justify-center rounded-md border border-foreground/[0.08] bg-transparent p-0 opacity-60 transition-all duration-[var(--duration-normal,200ms)] ease-out hover:opacity-100 disabled:pointer-events-none disabled:opacity-30",
				),
				button_next: cn(
					"inline-flex h-7 w-7 items-center justify-center rounded-md border border-foreground/[0.08] bg-transparent p-0 opacity-60 transition-all duration-[var(--duration-normal,200ms)] ease-out hover:opacity-100 disabled:pointer-events-none disabled:opacity-30",
				),
				month_grid: "w-full border-collapse space-y-1",
				weekdays: "flex",
				weekday: "text-muted-foreground rounded-md w-[var(--control-height-sm,2.25rem)] font-normal text-[0.8rem]",
				week: "flex w-full mt-[var(--space-2,0.5rem)]",
				day: "relative p-0 text-center text-sm focus-within:relative focus-within:z-20 [&:has([aria-selected])]:bg-accent [&:has([aria-selected].range-end)]:rounded-r-md [&:has([aria-selected].range-start)]:rounded-l-md first:[&:has([aria-selected])]:rounded-l-md last:[&:has([aria-selected])]:rounded-r-md",
				day_button:
					"inline-flex h-[var(--control-height-sm,2.25rem)] w-[var(--control-height-sm,2.25rem)] items-center justify-center rounded-md p-0 text-sm font-normal transition-all duration-[var(--duration-normal,200ms)] ease-out hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 aria-selected:opacity-100",
				selected:
					"bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground focus:bg-primary focus:text-primary-foreground",
				today: "bg-accent text-accent-foreground",
				outside:
					"day-outside text-muted-foreground aria-selected:bg-accent/50 aria-selected:text-muted-foreground",
				disabled: "text-muted-foreground opacity-50",
				range_start: "day-range-start range-start",
				range_end: "day-range-end range-end",
				range_middle:
					"aria-selected:bg-accent aria-selected:text-accent-foreground rounded-none",
				hidden: "invisible",
				...classNames,
			}}
			components={{
				Chevron: ({ orientation, className: chevronClassName }) => {
					const rotation =
						orientation === "left"
							? "rotate-90"
							: orientation === "right"
								? "-rotate-90"
								: orientation === "up"
									? "rotate-180"
									: "";
					return (
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							fill="none"
							stroke="currentColor"
							strokeWidth="2"
							strokeLinecap="round"
							strokeLinejoin="round"
							className={cn("h-4 w-4", rotation, chevronClassName)}
							aria-hidden="true"
						>
							<polyline points="6 9 12 15 18 9" />
						</svg>
					);
				},
			}}
			{...props}
		/>
		</>
	);
}
Calendar.displayName = "Calendar";

export { Calendar };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}

